package jd.core.test;

import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.function.IntSupplier;
import java.util.function.Supplier;

/** Constructs whose decompilation was fixed for the bytecode generated by recent javac versions. */
public class JavacConstructs {

    enum Mode {
        FIRST("a"), SECOND("b");

        private final String label;

        Mode(String label) {
            this.label = label;
        }

        int length() {
            assert label != null : "label";
            return label.length();
        }
    }

    static class Left {
        static class Builder {
            Left build() {
                return new Left();
            }
        }
    }

    static class Right {
        static class Builder {
            Right build() {
                return new Right();
            }
        }
    }

    static Object build(Left.Builder left, Right.Builder right) {
        return left.build() == null ? right.build() : left.build();
    }

    static int checked(boolean flag, int x) {
        if (flag) {
            assert x > 0 : "x";
        }
        return x;
    }

    static void unreachable(boolean flag) {
        if (flag) {
            assert false;
        }
    }

    static void directories(List<File> files, List<File> directories, List<File> regular, boolean recursive) {
        files.forEach(f -> {
            if (recursive && f.isDirectory()) {
                directories.add(f);
            } else if (f.isFile()) {
                regular.add(f);
            }
        });
    }

    static <R extends Collection<String>> List<R> partitions(Supplier<R> factory, int count) {
        List<R> partitions = new ArrayList<>(count);
        for (int i = 0; i < count; i++) {
            partitions.add(factory.get());
        }
        return partitions;
    }

    static IntSupplier sizeOf(Object collection) {
        return ((Collection<?>) collection)::size;
    }

    static int reader(InputStream in) throws IOException {
        try (InputStream stream = in) {
            return stream.read();
        }
    }

    static int withCatch(InputStream in) {
        try (InputStream stream = in) {
            return stream.read();
        } catch (IOException e) {
            return -1;
        }
    }

    static int withFinally(InputStream in, List<String> log) throws IOException {
        try (InputStream stream = in) {
            return stream.read();
        } finally {
            log.add("done");
        }
    }

    static int loop(List<InputStream> streams) throws IOException {
        int total = 0;
        for (InputStream in : streams) {
            try (InputStream stream = in) {
                int b = stream.read();
                if (b < 0) {
                    break;
                }
                if (b == 0) {
                    continue;
                }
                total += b;
            }
        }
        return total;
    }

    static void nested(InputStream first, InputStream second, List<Integer> out) throws IOException {
        try (InputStream a = first) {
            try (InputStream b = second) {
                out.add(a.read() + b.read());
            }
            out.add(a.read());
        }
    }

    static void created(File file, List<Integer> out) throws IOException {
        try (java.io.FileInputStream stream = new java.io.FileInputStream(file)) {
            out.add(stream.read());
        }
    }

    static void manualClose(InputStream in, List<Integer> out) throws IOException {
        try {
            out.add(in.read());
            in.close();
        } catch (Throwable t) {
            try {
                in.close();
            } catch (Throwable suppressed) {
                t.addSuppressed(suppressed);
            }
            throw t;
        }
    }

    static <R extends Collection<String>> void overloaded(StringBuilder builder, Supplier<R> factory) {
        builder.append(factory.get());
    }

    static <R extends Collection<String>> void otherParameter(List<Collection<String>> target, Supplier<R> factory) {
        target.add(factory.get());
    }

    static <R extends Collection<String>> int sizes(List<R> target, Supplier<R> factory, R extra) {
        target.add(factory.get());
        target.add(extra);
        return target.size();
    }

    static String text(Supplier<String> supplier, List<String> list) {
        list.add(supplier.get());
        return String.valueOf(supplier.get());
    }
}
